  "objectives": [
    {
      "id": 1,
      "objective": "Research capillary-wave atomization theory: wavelength, droplet size, threshold amplitude, film thickness limits, and mass flow capacity for ultrasonic atomization, with specific data for liquid metals (Cu alloys and Al)",
      "rationale": "Question 1 requires quantitative estimates of capillary wavelength (λ = (8πσ/(ρf²))^(1/3)), median droplet size (D50 ≈ 0.34λ), threshold amplitude, max film thickness, and mass flow rate per unit area/power. Need literature values and formulas with DOIs.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Research plate vibration modes, nodal lines, amplitude distribution on sonotrode-driven plates, and optimal impact point selection",
      "rationale": "Question 2 asks about flexural modes on the plate, how amplitude varies spatially, whether moving the stream higher could place it near a node, and methods to check (vibrometer, powder pattern).",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Research plate degradation: W-coating dissolution, oxidation, adhered metal, detuning from added mass, thermal cycling effects, and inspection/cleaning methods",
      "rationale": "Question 3 asks about what one run does to the W-coated plate and how to detect damage via generator readings.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Estimate mass flow rates through 0.5 mm and 1 mm nozzles at various pressures, and compare to plate atomization capacity",
      "rationale": "Question 4 requires Bernoulli/Torricelli flow calculations and comparison to plate capacity to explain melt runoff.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Research thermal effects: plate temperature rise, film cooling/freezing, hold time effects on melt temperature, and mid-pour amplitude changes",
      "rationale": "Question 5 asks about thermal management during ultrasonic atomization of high-melting alloys.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Synthesize findings to rank causes of Run B failure and propose a corrective plan for the next run",
      "rationale": "Question 6 requires integration of all findings to rank failure causes and give actionable recommendations.",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Create artifacts (tables, calculations) and submit final answer",
      "rationale": "Need to present quantitative estimates in tables and deliver a comprehensive answer.",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

